import { readFileSync } from "node:fs";
import { basename } from "node:path";

const report = JSON.parse(readFileSync("before.json", "utf8"));
let bad = 0;
for (const file of report.testResults) {
  if (file.assertionResults.length === 0) {
    console.log(`✘ ${basename(file.name)}  broke before any test ran: ${file.message.split(" imported")[0]}`);
    bad += 1;
    continue;
  }
  for (const t of file.assertionResults) {
    const id = t.title.split(":")[0];
    const first = (t.failureMessages[0] ?? "").split("\n")[0].replace(" // Object.is equality", "");
    if (t.status === "passed") {
      console.log(`✘ ${id}  passes on the unchanged code, so it proves nothing about the change`);
      bad += 1;
    } else if (first.startsWith("AssertionError")) {
      console.log(`✔ ${id}  fails on an assertion: ${first}`);
    } else {
      console.log(`✘ ${id}  fails, but not on an assertion: ${first}`);
      bad += 1;
    }
  }
}
process.exitCode = bad ? 1 : 0;

const LOCK = "/work/.nova/locked.json";  // outside the checkout
const digest = (rel: string) => createHash("sha256").update(readFileSync(resolve(REPO, rel))).digest("hex");

export const lock = (testFiles: string[]) =>
  writeFileSync(LOCK, JSON.stringify(Object.fromEntries(testFiles.map((rel) => [rel, digest(rel)]))));

export const denyLockedEdits: HookCallback = async (input) => {  // PreToolUse, matcher "Edit|Write"
  if (input.hook_event_name !== "PreToolUse") return {};
  const path = (input.tool_input as { file_path?: string }).file_path;
  if (!path || !Object.hasOwn(locked(), relative(REPO, resolve(path)))) return {};
  return { hookSpecificOutput: {
    hookEventName: "PreToolUse",
    permissionDecision: "deny",
    permissionDecisionReason: "This test is a locked QA check for this ticket. Add a new test instead, " +
      "or ask the requester to change the QA plan.",
  } };
};

