  writeFileSync(LOCK, JSON.stringify(Object.fromEntries(files.map((f) => [f, digest(f)])), null, 2));
  console.log(`locked ${files.length} test files`);
} else {
  const locked = JSON.parse(readFileSync(LOCK, "utf8"));
  const changed = Object.entries(locked).filter(([f, d]) => !existsSync(f) || digest(f) !== d).map(([f]) => f);
  console.log(changed.length ? `changed locked files: ${changed.join(", ")}` : "locked files unchanged");
  process.exitCode = changed.length ? 1 : 0;
}
