import { readFileSync } from "node:fs";
import { basename } from "node:path";

const report = JSON.parse(readFileSync("before.json", "utf8"));
const guards = new Set(process.argv.slice(2)); // QA IDs the plan marks as guards
let bad = 0;
for (const file of report.testResults) {
  if (file.assertionResults.length === 0) {
    console.log(`✘ ${basename(file.name)}  broke before any test ran: ${file.message.split(" imported")[0]}`);
    bad += 1;
    continue;
  }
  for (const t of file.assertionResults) {
    const id = t.title.split(":")[0];
    const first = (t.failureMessages[0] ?? "").split("\n")[0].replace(" // Object.is equality", "");
    if (t.status === "passed" && guards.has(id)) {
      console.log(`◦ ${id}  passes on the unchanged code, as a guard should`);
    } else if (t.status === "passed") {
      console.log(`✘ ${id}  passes on the unchanged code, so it proves nothing about the change`);
      bad += 1;
    } else if (first.startsWith("AssertionError")) {
      console.log(`✔ ${id}  fails on an assertion: ${first}`);
    } else {
      console.log(`✘ ${id}  fails, but not on an assertion: ${first}`);
      bad += 1;
    }
  }
}
process.exitCode = bad ? 1 : 0;
